
let data=[],trials=[],eid=null,currentRole=null,editVersion=0,refreshTimer=null,refreshing=false,pendingTrialId=null,editingTrialId=null;let selectedMembers=new Set(),selectedTrials=new Set();const $=x=>document.getElementById(x),money=x=>Number(x||0).toLocaleString("fr-FR")+" €";
let cameraStream=null,cameraKind=null,cameraFiles={photo:null,medical:null};let coachDocMemberId=null,coachDocKind=null,coachDocCameraFile=null;let loadedBackup=null,backupRestoreBusy=false;
function isPhoneDevice(){return /Android|iPhone|iPod|IEMobile|Opera Mini|Mobile/i.test(navigator.userAgent||"")&&!/iPad/i.test(navigator.userAgent||"")}
function setupDocumentInputs(){let mobile=isPhoneDevice();[["photo","image/*"],["medical","image/*,application/pdf"]].forEach(([kind,accept])=>{let input=$(kind+"File"),actions=$(kind+"DesktopActions");if(!input)return;input.accept=accept;if(mobile){input.classList.remove("desktop-doc-input");input.setAttribute("capture","environment");if(actions)actions.style.display="none"}else{input.classList.add("desktop-doc-input");input.removeAttribute("capture");if(actions)actions.style.display="flex"}})}
