async function startCamera(kind){cameraKind=kind;cameraError.textContent="";let baseKind=String(kind||"").replace(/^coach-/,"");cameraTitle.textContent=baseKind==="photo"?"Photo de l’adhérent":"Photo du certificat médical";try{if(!navigator.mediaDevices?.getUserMedia)throw new Error("La caméra n’est pas disponible dans ce navigateur.");cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}},audio:false});cameraVideo.srcObject=cameraStream;cameraM.classList.add("open")}catch(err){closeCamera();alert("Impossible d’ouvrir la caméra : "+err.message)}}
