function age(b){if(!b)return 0;let d=new Date(b),t=new Date(),a=t.getFullYear()-d.getFullYear();if(new Date(t.getFullYear(),d.getMonth(),d.getDate())>t)a--;return a}
function normalizePhone(v){return String(v||"").replace(/\D/g,"")}
function formatPhone(v){let d=normalizePhone(v).slice(0,10);return d.replace(/(\d{2})(?=\d)/g,"$1 ")}
