function validEmail(v){let e=String(v||"").trim();return !e||/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)}
function displaySex(v){return v==="Fille"?"Femme":v==="Garçon"?"Homme":v}
const ADO_ACTS=["Boxe ados","MMA Ado","Striking ados"],ADULT_ACTS=["Boxe adultes","Grappling","Striking adultes"];
function disciplinePrice(selected){let a=selected||[],hasBaby=a.includes("Baby boxe"),hasChild=a.includes("Boxe enfants"),ado=a.filter(x=>ADO_ACTS.includes(x)),adult=a.filter(x=>ADULT_ACTS.includes(x));if(!a.length)return{valid:false,value:0,reason:"Sélectionnez au moins une discipline."};if(hasBaby&&a.length>1)return{valid:false,value:0,reason:"Baby boxe ne peut pas être combinée avec une autre discipline."};if(hasChild&&a.length>1)return{valid:false,value:0,reason:"Boxe enfants ne peut pas être combinée avec une autre discipline."};if(ado.length&&adult.length)return{valid:false,value:0,reason:"Les disciplines Ado et Adultes ne peuvent pas être combinées."};if(hasBaby)return{valid:true,value:130};if(hasChild)return{valid:true,value:220};if(ado.length)return{valid:true,value:ado.length===1?220:ado.length===2?340:380};if(adult.length)return{valid:true,value:adult.length===1?270:adult.length===2?350:400};return{valid:false,value:0,reason:"Combinaison de disciplines non reconnue."}}
function sameFamilyAddress(a,b){return !!(a&&b&&a.address&&a.zip&&a.city&&b.address&&b.zip&&b.city&&(a.address||"").trim().toLowerCase()===(b.address||"").trim().toLowerCase()&&String(a.zip||"").trim()===String(b.zip||"").trim()&&(a.city||"").trim().toLowerCase()===(b.city||"").trim().toLowerCase())}
function createdRank(m){let t=Date.parse(m&&m.created_at||"");return Number.isFinite(t)?t:Number.MAX_SAFE_INTEGER}
function familyMembers(m){if(!m||!m.address||!m.zip||!m.city)return [m];let list=data.filter(x=>x.id!==m.id&&sameFamilyAddress(x,m));list.push(m);return list.sort((a,b)=>createdRank(a)-createdRank(b)||String(a.id||"").localeCompare(String(b.id||"")))}
function familyInfo(m){let list=familyMembers(m),pos=Math.max(0,list.findIndex(x=>x===m||x.id===m.id))+1;if(!pos)pos=list.length;return{size:list.length,position:pos,discount:pos>=2&&pos<=4?20:0}}
function family(m){return familyInfo(m).size}
function calc(m){let fi=familyInfo(m),disc=fi.discount,pricing=disciplinePrice(m.acts||[]),theory=pricing.valid?pricing.value:0,sug=Math.max(0,theory-disc),stored=m.due==null?null:Number(m.due),due;if(stored==null||!Number.isFinite(stored))due=sug;else if(!disc&&theory>=20&&Math.abs(stored-(theory-20))<0.001)due=theory;else due=Math.min(stored,sug);let paid=(m.payments||[]).reduce((s,p)=>s+(+p.amount||0),0),rest=Math.max(0,due-paid),paymentStatus=due===0?"Gratuit":paid>=due?"À jour":paid?"Partiel":"Impayé";return{disc,theory,sug,due,paid,rest,paymentStatus,status:paymentStatus,familyPosition:fi.position,familySize:fi.size}}
function statusReasons(m,x=calc(m),includeMedical=true){let reasons=[];if(x.rest>0)reasons.push("Défaut de paiement");if(includeMedical&&!m.medical_path)reasons.push("Certificat médical manquant");if(!m.photo_path)reasons.push("Photo manquante");return reasons}
function fullMemberStatus(m,x=calc(m)){let reasons=statusReasons(m,x,true);return{ok:reasons.length===0,reasons,label:reasons.length?"Pas à jour":"À jour"}}
function statusHtml(m,x=calc(m)){let s=fullMemberStatus(m,x);return s.ok?"<span class='status-ok'>● À jour</span>":`<span class='status-due'>⚠ Pas à jour</span><div class='small'>${s.reasons.join(" · ")}</div>`}
function render(){let z=data.map(m=>({m,x:calc(m),s:fullMemberStatus(m)}));n.textContent=data.length;girls.textContent=data.filter(x=>displaySex(x.sex)==="Femme").length;boys.textContent=data.filter(x=>displaySex(x.sex)==="Homme").length;paidMembers.textContent=z.filter(o=>o.s.ok).length;dueMembers.textContent=z.filter(o=>o.x.rest>0).length;alreadyPaid.textContent=money(z.reduce((s,o)=>s+o.x.paid,0));notPaid.textContent=money(z.reduce((s,o)=>s+o.x.rest,0));let all=data.flatMap(m=>m.payments||[]);let totalBy=name=>all.filter(p=>p.method===name).reduce((s,p)=>s+(Number(p.amount)||0),0);cashTotal.textContent=money(totalBy("Espèces"));checkTotal.textContent=money(totalBy("Chèque"));couponTotal.textContent=money(totalBy("Coupons Sport"));labazTotal.textContent=money(totalBy("LABAZ"));passTotal.textContent=money(totalBy("Pass Sport"));ancvTotal.textContent=money(totalBy("Chèque ANCV"));deleteAllBtn.disabled=!data.length;deleteAllTrialsBtn.disabled=!trials.length;adminRows();coachRows();trialRowsRender();applyRole()}
function selectedValues(el){return el?[...el.selectedOptions].map(o=>o.value):[]}
function trialForMember(m){return trials.find(t=>samePerson(t,m))||null}
