function adminRows(){let visible=data.filter(memberMatchesSearch);rows.innerHTML=visible.map(m=>{let x=calc(m),trialActs=trialActsForMember(m),st=statusHtml(m,x);return`<tr><td class="select-col"><input type="checkbox" style="width:auto" ${selectedMembers.has(m.id)?"checked":""} onchange="toggleMemberSelection('${m.id}',this.checked)"></td><td>${st}</td><td><button class="link" onclick="profileShow('${m.id}','admin')">${m.first} ${m.last}</button></td><td>${displaySex(m.sex)}</td><td>${age(m.birth)} ans</td><td>${formatPhone(m.phone)}</td><td>${disciplineTags(m.acts||[])}</td><td>${trialActs.length?disciplineTags(trialActs,true):""}</td><td>${x.disc?"−20 €":"—"}</td><td>${money(x.due)}</td><td>${money(x.paid)}</td><td>${money(x.rest)}</td><td><button onclick="openForm('${m.id}')">Modifier</button> <button class="danger" onclick="deleteOneMember('${m.id}')">Supprimer</button></td></tr>`}).join("")||"<tr><td colspan=13>Aucun adhérent</td></tr>";updateMemberSelectionUi()}
