function parseStoredZip(buffer){let b=new Uint8Array(buffer),dv=new DataView(buffer),dec=new TextDecoder(),files={},p=0;while(p+4<=b.length){let sig=dv.getUint32(p,true);if(sig===0x02014b50||sig===0x06054b50)break;if(sig!==0x04034b50)throw new Error("Archive ZIP invalide.");if(p+30>b.length)throw new Error("Archive ZIP tronquée.");let flags=dv.getUint16(p+6,true),method=dv.getUint16(p+8,true),crc=dv.getUint32(p+14,true),csize=dv.getUint32(p+18,true),usize=dv.getUint32(p+22,true),nlen=dv.getUint16(p+26,true),xlen=dv.getUint16(p+28,true);if(flags!==0||method!==0||csize!==usize)throw new Error("Format ZIP non pris en charge. Utilisez le fichier créé directement par SGS Gestion.");let ns=p+30,ds=ns+nlen+xlen,de=ds+csize;if(de>b.length)throw new Error("Archive ZIP incomplète.");let name=dec.decode(b.slice(ns,ns+nlen)),content=b.slice(ds,de);if(crc32(content)!==crc)throw new Error("Archive corrompue (contrôle CRC incorrect).");files[name]=content;p=de}return files}
